var WELLKNOWN={20:'FTP 数据',21:'FTP 控制',22:'SSH',23:'Telnet',25:'SMTP',53:'DNS',80:'HTTP',110:'POP3',143:'IMAP',443:'HTTPS',445:'SMB',3306:'MySQL',3389:'RDP',5432:'PostgreSQL',6379:'Redis',8080:'HTTP 代理',8443:'HTTPS 备用',9000:'常见开发端口'};
function expandPorts(spec){
  spec=(spec||'').trim();
  if(!spec) return {valid:false,error:'空输入',ports:[],count:0};
  var ports=[], invalid=[];
  var parts=spec.split(',');
  for(var k=0;k<parts.length;k++){
    var p=parts[k].trim(); if(!p) continue;
    var rng=p.split('-');
    if(rng.length===2){
      var a=parseInt(rng[0],10), b=parseInt(rng[1],10);
      if(isNaN(a)||isNaN(b)||a<0||b>65535||a>b){ invalid.push(p); continue; }
      for(var i=a;i<=b;i++) ports.push(i);
    } else {
      var v=parseInt(p,10);
      if(isNaN(v)||v<0||v>65535){ invalid.push(p); continue; }
      ports.push(v);
    }
  }
  var seen={}, uniq=[];
  for(var j=0;j<ports.length;j++){ if(!seen[ports[j]]){ seen[ports[j]]=1; uniq.push(ports[j]); } }
  uniq.sort(function(x,y){return x-y;});
  if(uniq.length>100000) return {valid:false,error:'端口数过多(>100000)',ports:[],count:0};
  var named=[];
  for(var n=0;n<uniq.length;n++){ if(uniq[n] in WELLKNOWN) named.push({port:uniq[n],service:WELLKNOWN[uniq[n]]}); }
  return {valid: invalid.length===0 && uniq.length>0, ports:uniq, count:uniq.length, invalid:invalid, named:named};
}

var EXPORTS={expandPorts:expandPorts};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PortScanForgePure = EXPORTS; }
